class HasEnduringBestSellerStreak2 {
  public boolean solve(String[] bestSeller, int k) {
    int l = 0, r = 0;
    while (r < bestSeller.length) {
      boolean canGrow = l == r || bestSeller[l].equals(bestSeller[r]);
